[{"type": "text", "text": "{
  "paperId": "09d42292188928b84db6f3fd5ecab959ceea5432",
  "title": "Research on the Application of Computer Vision Based on Deep Learning in Autonomous Driving Technology",
  "openAccessPdf": {
    "url": "",
    "status": null,
    "license": null,
    "disclaimer": "Notice: Paper or abstract available at https://arxiv.org/abs/2406.00490, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
  },
  "authors": [
    {
      "authorId": "2299103433",
      "name": "Jingyu Zhang"
    },
    {
      "authorId": "2304903182",
      "name": "Jin Cao"
    },
    {
      "authorId": "2293383854",
      "name": "Jinghao Chang"
    },
    {
      "authorId": "2304521131",
      "name": "Xinjin Li"
    },
    {
      "authorId": "2290022873",
      "name": "Houze Liu"
    },
    {
      "authorId": "2290100121",
      "name": "Zhenglin Li"
    }
  ],
  "abstract": "This research aims to explore the application of deep learning in autonomous driving computer vision technology and its impact on improving system performance. By using advanced technologies such as convolutional neural networks (CNN), multi-task joint learning methods, and deep reinforcement learning, this article analyzes in detail the application of deep learning in image recognition, real-time target tracking and classification, environment perception and decision support, and path planning and navigation. Application process in key areas. Research results show that the proposed system has an accuracy of over 98% in image recognition, target tracking and classification, and also demonstrates efficient performance and practicality in environmental perception and decision support, path planning and navigation. The conclusion points out that deep learning technology can significantly improve the accuracy and real-time response capabilities of autonomous driving systems. Although there are still challenges in environmental perception and decision support, with the advancement of technology, it is expected to achieve wider applications and greater capabilities in the future. potential."
}", "annotations": null, "meta": null}, {"type": "text", "text": "{
  "paperId": "58d691deb026017dfb107084fd73224b9eaa7dc3",
  "title": "Deep learning based computer vision under the prism of 3D point clouds: a systematic review",
  "openAccessPdf": {
    "url": "https://link.springer.com/content/pdf/10.1007/s00371-023-03237-7.pdf",
    "status": "HYBRID",
    "license": "CCBY",
    "disclaimer": "Notice: Paper or abstract available at https://api.unpaywall.org/v2/10.1007/s00371-023-03237-7?email=<INSERT_YOUR_EMAIL> or https://doi.org/10.1007/s00371-023-03237-7, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
  },
  "authors": [
    {
      "authorId": "2181713430",
      "name": "Kyriaki A. Tychola"
    },
    {
      "authorId": "2280221",
      "name": "Eleni Vrochidou"
    },
    {
      "authorId": "2947691",
      "name": "G. Papakostas"
    }
  ],
  "abstract": "Point clouds consist of 3D data points and are among the most considerable data formats for 3D representations. Their popularity is due to their broad application areas, such as robotics and autonomous driving, and their employment in basic 3D vision tasks such as segmentation, classification, and detection. However, processing point clouds is challenging compared to other visual forms such as images, mainly due to their unstructured nature. Deep learning (DL) has been established as a powerful tool for data processing, reporting remarkable performance enhancements compared to traditional methods for all basic 2D vision tasks. However new challenges are emerging when it comes to processing unstructured 3D point clouds. This work aims to guide future research by providing a systematic review of DL on 3D point clouds, holistically covering all 3D vision tasks. 3D technologies of point cloud formation are reviewed and compared to each other. The application of DL methods for point cloud processing is discussed, and state-of-the-art models’ performances are compared focusing on challenges and solutions. Moreover, in this work the most popular 3D point cloud benchmark datasets are summarized based on their task-oriented applications, aiming to highlight existing constraints and to comparatively evaluate them. Future research directions and upcoming trends are also highlighted."
}", "annotations": null, "meta": null}, {"type": "text", "text": "{
  "paperId": "5cdde049463b912600882376e5488b20a998657d",
  "title": "Computer Vision Technology for Monitoring of Indoor and Outdoor Environments and HVAC Equipment: A Review",
  "openAccessPdf": {
    "url": "https://www.mdpi.com/1424-8220/23/13/6186/pdf?version=1688626038",
    "status": "GOLD",
    "license": "CCBY",
    "disclaimer": "Notice: Paper or abstract available at https://pmc.ncbi.nlm.nih.gov/articles/PMC10346506, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
  },
  "authors": [
    {
      "authorId": "2158327821",
      "name": "Bin Yang"
    },
    {
      "authorId": "2194129790",
      "name": "Shuang Yang"
    },
    {
      "authorId": "2204455479",
      "name": "Xin Zhu"
    },
    {
      "authorId": "2221882979",
      "name": "Min Qi"
    },
    {
      "authorId": "2222312759",
      "name": "He Li"
