  "paperId": "224ecc21a917dd246420d2da0b3edee5834f3391",
  "title": "Vision Transformers in Medical Computer Vision - A Contemplative Retrospection",
  "openAccessPdf": {
    "url": "http://arxiv.org/pdf/2203.15269",
    "status": "GREEN",
    "license": null,
    "disclaimer": "Notice: Paper or abstract available at https://arxiv.org/abs/2203.15269, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
  },
  "authors": [
    {
      "authorId": "2160629993",
      "name": "Arshi Parvaiz"
    },
    {
      "authorId": "2160630451",
      "name": "Muhammad Anwaar Khalid"
    },
    {
      "authorId": "2160629668",
