  "paperId": "d8e4e44c32ea609becf46d569f459bc97f5a2184",
  "title": "Media Arts: Arts Education for a Digital Age",
  "year": 2010,
  "openAccessPdf": {
    "url": "https://journals.sagepub.com/doi/pdf/10.1177/016146811011200806",
    "status": "CLOSED",
    "license": null,
    "disclaimer": "Notice: Paper or abstract available at https://api.unpaywall.org/v2/10.1177/016146811011200806?email=<INSERT_YOUR_EMAIL> or https://doi.org/10.1177/016146811011200806, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
  },
  "authors": [
